import React, { Component } from "react";
import "./Aboutus.css";

export default class Aboutus extends Component {
    render() {
        return (
           <div>
          <div className="about-containerr">
                <div className="about-rectangle">
                    <h1 className="TaiLink-About">TaiLink</h1>
                    <div className="sen1">
                <p>TaiLink helps locate lost or stolen pets through the use of a microchip implanted in them. Our website has many features:</p>
                <p>Enabling them to provide updates via the chip's identification number.</p>
                <p>Users can also post information about lost pets that have not yet been found or animals in need of assistance.</p>
                <p>Suggestions for veterinary services or suitable homes can also be provided.</p>
                </div>
                </div>
        </div>
        </div>

        );
    }
}
